# Mainland China sets the full-width marks in the left of the box, and
# 。，、 in its lower left (GB/T 15834); Taiwan centres them. The fonts take
# Taiwan's by default and these where text is tagged Simplified Chinese
# (OpenType locl, language ZHS).
def _moved(strokes, dx, dy):
    from skeleton import transform
    return [(k, transform(d, lambda p: (p[0] + dx, p[1] + dy))) for k, d in strokes]


ZHS = {ch: _moved(C[ch], dx, dy) for ch, dx, dy in (
    ('。', -270, 300), ('，', -270, 260), ('、', -260, 280),
    ('；', -280, 0), ('：', -280, 0), ('？', -270, 0), ('！', -280, 0))}
